<?php namespace App\Notifications; use App\Models\Product; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Notifications\Notification; class LowStockNotification extends Notification implements ShouldQueue {use Queueable; public function __construct(public Product $product){} public function via(object $n):array{return ['database','mail'];} public function toArray(object $n):array{return ['product_id'=>$this->product->id,'message'=>"{$this->product->name} is running low on stock."];} }
